    internal_ln(re, im, str) {
      if ("object" == typeof re) {
        im = re.im;
        re = re.re;
      }
      let nre = lnHypot(re, im),
        nim = atg(re, im);
      return str ? strBuild(nre, nim) : { re: nre, im: nim };
    }

    internal_arc(cos, sin, hyp = undefined, str) {
      if (!hyp) {
        let sqre = cos.re ** 2 - cos.im ** 2 + sin.re ** 2 - sin.im ** 2,
          sqim = 2 * cos.re * cos.im + 2 * sin.re * sin.im;
        hyp = this.internal_sqrt(sqre, sqim);
      }
      const num = this.internal_ln(
          cos.re + sin.im,
          cos.im - sin.re,
          false, // objects
        ),
        den = this.internal_ln(hyp.re, hyp.im, false),
        iln = { re: den.im - num.im, im: num.re - den.re };
      return str ? strBuild(iln) : iln;
    }

    internal_twod_to_real(base, n, str) {
      if (n == 0) return { re: 1, im: 0 };
      if (n == 1) return base;
      if (base.im == 0) {
        if (base.re == 1) return { re: 1, im: 0 };
        if (base.re == 0)
          return n < 0 ? { re: Infinity, im: Infinity } : { re: 0, im: 0 };
        let hyp = abs(base.re) ** n;
        if (base.re > 0) return { re: hyp, im: 0 };
        const angle = PI * (n % 2);
        return this.internal_polar(hyp, angle);
      }
      if (n < 0) {
        const mag = base.re ** 2 + base.im ** 2;
        return this.internal_twod_to_real(
          { re: base.re / mag, im: -base.im / mag },
          -n,
          str,
        );
      }
      // I'll use binary decomposition lol
      let ret = { re: 1, im: 0 },
        pow = base,
        rem = 1;
      while (n >= 1) {
        // while there is still a whole part
        if (n % rem != n % (rem << 1)) {
          // if a bit is found in the power-of-two
          n -= rem;
          ret = multiply(ret, pow, false);
        }
        rem <<= 1;
        pow = multiply(pow, pow, false);
      }
      pow = base;
      rem = 1;
      while (n > 1e-15) {
        // while there is still a decimal part
        if (n > rem) {
          // if this power-of-two fits in the exponent
          n -= rem;
          ret = multiply(ret, pow, false);
        }
        rem >>= 1;
        pow = this.internal_sqrt(pow);
      }
      return str ? strBuild(ret) : ret;
    }

    internal_twod_to_imag(base, n) {
      if (n == 0) return { re: 1, im: 0 };
      if (base.im == 0) {
        if (base.re == 1) return { re: 1, im: 0 };
        if (base.re == 0) return { re: NaN, im: NaN };
      }
      return this.internal_polar(
        exp(-n * atg(base.re, base.im)),
        (lnHypot(base.re, base.im) * n) % (2 * PI),
      );
    }

    internal_tric_real(c) {
      let guess = (c + 8) / 9,
        kre = Infinity;
      while (kre > 1e-18) {
        // it's Newton time!
        kre = (4 * guess ** 3 - 3 * guess - c) / (12 * guess * guess - 3);
        guess -= kre;
      }
      return guess;
    }

    internal_tric_complex(cre, cim, str) {
      if ("object" == typeof cre) {
        cim = cre.im;
        cre = cre.re;
      } // cre, cim means from Cosine the REal and IMaginary parts
      let a = (cre + 8) / 9,
        b = cim / 9,
        kre = Infinity,
        kim = 0; // kre, kim are the difference
      while (kre ** 2 + kim ** 2 > 1e-18) {
        // it's Newton time!
        const nre = 4 * a * a * a - 12 * a * b * b - 3 * a - cre,
          nim = 12 * a * a * b - 4 * b * b * b - 3 * b - cim, // $f(x) = 4x^3 -3x -c$
          dre = 12 * (a * a - b * b) - 3,
          dim = 24 * a * b,
          inv = dre * dre + dim * dim; // $df(x) = 12x^2 -3$
        if (inv == 0) break;
        kre = (nre * dre + nim * dim) / inv;
        kim = (nim * dre - nre * dim) / inv; // $\Delta = \frac{f(x)}{df(x)}$
        a -= kre;
        b -= kim;
      }
      return str ? strBuild(a, b) : { re: a, im: b }; // NOTE: Very expensive calcs, use sparingly
    }

    internal_cbrt(re, im, str) {
      if ("object" == typeof re) {
        im = re.im;
        re = re.re;
      }
      let radius = hypot(re, im),
        nre = this.internal_tric_real(re / radius),
        nim = sqrt(1 - nre * nre) * (im < 0 ? -1 : 1);
      radius = cbrt(radius);
      let ret = { re: nre * radius, im: nim * radius };
      return str ? strBuild(ret) : ret;
    }

