    decimalComplex({ COMPLEX, OPERATION, DECIMALS }) {
      try {
        const p = strParse(COMPLEX);
        OPERATION = OPERATION.toLowerCase();
        let fac = 10 ** (DECIMALS || 0),
          func;
        switch (OPERATION) {
          case "round up":
          case "round":
            func = Math.round;
            break;
          case "ceil of":
          case "ceil":
            func = ceil;
            break;
          case "floor of":
          case "floor":
            func = floor;
            break;
          case "truncate":
          case "trunc":
            func = trunc;
            break;
          default:
            return NaN;
        }
        let r = strBuild(func(p.re * fac) / fac, func(p.im * fac) / fac);
        if (this.noSpacing) r = r.replace(/\s+/g, "");
        return r;
      } catch (e) {
        console.log(e);
        return 0;
      }
    }

